# get(key, default=None) - 获取值，不存在返回默认值
d = {'a': 1, 'b': 2}
print(d.get('a'))      # 1
print(d.get('c'))      # None
print(d.get('c', 0))   # 0

# setdefault(key, default=None) - 获取值，不存在则设置并返回
d = {'a': 1}
val = d.setdefault('b', 2)
print(d)    # {'a': 1, 'b': 2}
print(val)  # 2
val = d.setdefault('a', 99)
print(val)  # 1（已存在，返回原值）
print(d)    # {'a': 1, 'b': 2}（不改变）

# update([other]) - 更新字典
d = {'a': 1, 'b': 2}
d.update({'b': 20, 'c': 30})
print(d)  # {'a': 1, 'b': 20, 'c': 30}
d.update(d=40, e=50)
print(d)  # {'a': 1, 'b': 20, 'c': 30, 'd': 40, 'e': 50}

# pop(key[, default]) - 删除并返回指定键的值
d = {'a': 1, 'b': 2, 'c': 3}
val = d.pop('b')
print(val)  # 2
print(d)    # {'a': 1, 'c': 3}
val = d.pop('x', '不存在')
print(val)  # '不存在'

# popitem() - 删除并返回最后一个键值对
d = {'a': 1, 'b': 2, 'c': 3}
item = d.popitem()
print(item)  # ('c', 3)
print(d)     # {'a': 1, 'b': 2}

# clear() - 清空字典
d = {'a': 1, 'b': 2}
d.clear()
print(d)  # {}

# copy() - 浅拷贝
d1 = {'a': 1, 'b': [2, 3]}
d2 = d1.copy()
d2['b'][0] = 99
print(d1)  # {'a': 1, 'b': [99, 3]}（嵌套对象共享）

# keys() - 返回所有键
print(d1.keys())  # dict_keys(['a', 'b'])

# values() - 返回所有值
print(d1.values())  # dict_values([1, [99, 3]])

# items() - 返回所有键值对
print(d1.items())  # dict_items([('a', 1), ('b', [99, 3])])

# fromkeys(iterable, value=None) - 创建新字典
d = dict.fromkeys(['x', 'y', 'z'], 0)
print(d)  # {'x': 0, 'y': 0, 'z': 0}

# 清晰度语法（Python 3.9+）
d1 = {'a': 1, 'b': 2}
d2 = {'b': 3, 'c': 4}
merged = d1 | d2
print(merged)  # {'a': 1, 'b': 3, 'c': 4}

# 字典推导式
squares = {x: x**2 for x in range(6)}
print(squares)  # {0: 0, 1: 1, 2: 4, 3: 9, 4: 16, 5: 25}

# 带条件的推导式
evens = {x: x**2 for x in range(10) if x % 2 == 0}
print(evens)  # {0: 0, 2: 4, 4: 16, 6: 36, 8: 64}

# 键值互换
original = {'a': 1, 'b': 2, 'c': 3}
inverted = {v: k for k, v in original.items()}
print(inverted)  # {1: 'a', 2: 'b', 3: 'c'}

# 过滤字典
prices = {'apple': 5, 'banana': 3, 'cherry': 8, 'date': 2}
expensive = {k: v for k, v in prices.items() if v > 4}
print(expensive)  # {'apple': 5, 'cherry': 8}

# 按值排序
d = {'c': 3, 'a': 1, 'b': 2}
sorted_by_value = dict(sorted(d.items(), key=lambda item: item[1]))
print(sorted_by_value)  # {'a': 1, 'b': 2, 'c': 3}

# Counter 统计频率
from collections import Counter
words = 'hello world hello python world hello'.split()
word_count = Counter(words)
print(word_count)  # Counter({'hello': 3, 'world': 2, 'python': 1})
print(word_count.most_common(2))  # [('hello', 3), ('world', 2)]

# defaultdict 设置默认值
from collections import defaultdict
dd = defaultdict(list)
for k, v in [('a', 1), ('a', 2), ('b', 3)]:
    dd[k].append(v)
print(dict(dd))  # {'a': [1, 2], 'b': [3]}

# 字典遍历技巧
d = {'name': 'Alice', 'age': 25, 'city': 'Beijing'}
for key in d:           # 遍历键
    print(key)
for value in d.values():  # 遍历值
    print(value)
for k, v in d.items():   # 遍历键值对
    print(f'{k}: {v}')

# add(elem) - 添加元素
s = {1, 2, 3}
s.add(4)
print(s)  # {1, 2, 3, 4}
s.add(2)  # 已存在，不变
print(s)  # {1, 2, 3, 4}

# remove(elem) - 删除元素，不存在抛 KeyError
s = {1, 2, 3}
s.remove(2)
print(s)  # {1, 3}
# s.remove(99)  # KeyError

# discard(elem) - 删除元素，不存在不报错
s = {1, 2, 3}
s.discard(2)
print(s)  # {1, 3}
s.discard(99)  # 不报错
print(s)  # {1, 3}

# pop() - 删除并返回任意元素
s = {1, 2, 3}
elem = s.pop()
print(elem)  # 1（或 2 或 3）

# clear() - 清空集合
s = {1, 2, 3}
s.clear()
print(s)  # set()

# 集合运算
a = {1, 2, 3, 4}
b = {3, 4, 5, 6}

# union() 或 | - 并集
print(a | b)              # {1, 2, 3, 4, 5, 6}
print(a.union(b))         # {1, 2, 3, 4, 5, 6}

# intersection() 或 & - 交集
print(a & b)              # {3, 4}
print(a.intersection(b))  # {3, 4}

# difference() 或 - - 差集
print(a - b)              # {1, 2}
print(a.difference(b))    # {1, 2}

# symmetric_difference() 或 ^ - 对称差集
print(a ^ b)                        # {1, 2, 5, 6}
print(a.symmetric_difference(b))    # {1, 2, 5, 6}

# 子集与超集判断
a = {1, 2}
b = {1, 2, 3, 4}
print(a.issubset(b))       # True（a 是 b 的子集）
print(a.issuperset({1}))   # True（a 是 {1} 的超集）
print(a.isdisjoint({5, 6}))  # True（没有交集）

# 原地更新运算
a = {1, 2, 3}
a.update({4, 5})         # a |= {4, 5}
print(a)  # {1, 2, 3, 4, 5}

a.intersection_update({3, 4, 5})  # a &= {3, 4, 5}
print(a)  # {3, 4, 5}

a.difference_update({5})  # a -= {5}
print(a)  # {3, 4}

a.symmetric_difference_update({3, 6})  # a ^= {3, 6}
print(a)  # {4, 6}
